Here's how to handle each scenario with modern MSTest (3.9+/3.10+):

```csharp
[TestClass]
public sealed class MyTests
{
    private string? _tempFile;

    // 1. Windows-only (registry access)
    [TestMethod]
    [OSCondition(OperatingSystems.Windows)]
    public void Registry_ReadsExpectedValue()
    {
        var value = Registry.GetValue(@"HKEY_LOCAL_MACHINE\SOFTWARE\MyApp", "Setting", null);
        Assert.IsNotNull(value);
    }

    // 2. Skip in CI (requires local GPU)
    [TestMethod]
    [CICondition(ConditionMode.Exclude)]
    public void RenderFrame_ProducesExpectedOutput()
    {
        var result = GpuRenderer.RenderFrame();
        Assert.IsNotNull(result);
    }

    // 3. Flaky external API — retry up to 3 times
    [TestMethod]
    [Retry(3)]
    [Timeout(10000)]
    public async Task WeatherApi_ReturnsForecast(TestContext testContext)
    {
        var forecast = await _client.GetForecastAsync(testContext.CancellationToken);
        Assert.IsNotNull(forecast);
    }

    // 4. Temp file cleanup — TestCleanup runs even on failure
    [TestMethod]
    public void Export_WritesValidFile()
    {
        _tempFile = Path.GetTempFileName();
        MyExporter.Export(_tempFile);
        Assert.IsTrue(File.Exists(_tempFile));
    }

    [TestCleanup]
    public void Cleanup()
    {
        if (_tempFile is not null && File.Exists(_tempFile))
        {
            File.Delete(_tempFile);
        }
    }
}
```

**Key points:**

| Scenario | Attribute/Pattern | MSTest version |
|----------|-------------------|----------------|
| OS-specific | `[OSCondition(OperatingSystems.Windows)]` | 3.10+ |
| Skip in CI | `[CICondition(ConditionMode.Exclude)]` | 3.10+ |
| Flaky retry | `[Retry(3)]` | 3.9+ |
| Guaranteed cleanup | `[TestCleanup]` method | All versions |

`[TestCleanup]` always runs after each test (even on failure), making it ideal for releasing resources. Combine with `[Timeout]` + `CancellationToken` on async tests to avoid hangs.
